import collections
from itertools import zip_longest
from random import choices
def task_func(l1, l2, K=10):
    _missing = object()
    combined = [elem for pair in zip_longest(l1, l2, fillvalue=_missing) for elem in pair if elem is not _missing]
    sample = choices(combined, k=K)
    counts = collections.Counter(sample)
    total = len(sample)
    if total == 0:
        return collections.Counter()
    return collections.Counter({elem: cnt / total for elem, cnt in counts.items()})

import collections
from itertools import zip_longest
from random import choices
def task_func(l1, l2, K=10):
    _missing = object()
    combined = [elem for pair in zip_longest(l1, l2, fillvalue=_missing) for elem in pair if elem is not _missing]
    unique_elements = []
    for elem in combined:
        if elem not in unique_elements:
            unique_elements.append(elem)
    sample = choices(unique_elements, k=K)
    return collections.Counter(sample)
